options(mc.cores=1L);source('cellchat_nichechat_fibro7/scripts/nichenet_common.R');setDTthreads(1);library(CellChat)
O<-'results/C5_Endothelial_NicheNet_spatial_v1';e<-fread(file.path(O,'06_CellChat_integration/full_evidence.tsv'));su<-fread(file.path(O,'03_candidate_ligands/expression_summary.tsv'));c5<-su[group=='Fibro_C5'];setnames(c5,setdiff(names(c5),'gene'),paste0('C5_',setdiff(names(c5),'gene')));e<-merge(e,c5,by.x='test_ligand',by.y='gene',all.x=TRUE);db<-CellChatDB.human
subunits<-function(g){if(is.na(g))return(NA_character_);if(g%in%rownames(db$complex)){v<-unlist(db$complex[g,,drop=FALSE],use.names=FALSE);paste(v[!is.na(v)&nzchar(v)],collapse=';')}else g};e[,required_subunits:=vapply(receptor,subunits,character(1))];rs<-su[group=='Endothelial'];e[,Endo_min_subunit_pct:=vapply(strsplit(required_subunits,';',fixed=TRUE),function(gs)if(anyNA(gs)||!all(gs%in%rs$gene))NA_real_ else min(rs[match(gs,gene),pooled_pct]),numeric(1))];e[,Endo_min_subunit_support_patients:=vapply(strsplit(required_subunits,';',fixed=TRUE),function(gs)if(anyNA(gs)||!all(gs%in%rs$gene))NA_real_ else min(rs[match(gs,gene),support_patients]),numeric(1))]
pairs<-fread(file.path(O,'03_candidate_ligands/broad_LR_all.tsv'))[eligible==TRUE];rr<-pairs[,.(NicheNet_expressed_receptors=paste(sort(unique(receptor)),collapse=';')),by=ligand];e<-merge(e,rr,by.x='test_ligand',by.y='ligand',all.x=TRUE)
links<-unique(rbind(fread(file.path(O,'05_ligand_target_links/top10_links.tsv')),fread(file.path(O,'05_ligand_target_links/selected_axis_links.tsv'))));tt<-links[,.(predicted_targets=paste(sort(unique(target)),collapse=';'),n_reported_targets=uniqueN(target)),by=.(ligand,program)];e<-merge(e,tt,by.x=c('test_ligand','program'),by.y=c('ligand','program'),all.x=TRUE);e[,target_link_status:=ifelse(is.na(n_reported_targets),'NOT_EXTRACTED_OR_NO_TOP250_PROGRAM_TARGET','EXTRACTED_TOP250_INTERSECTION')]
fwrite(e,file.path(O,'06_CellChat_integration/complete_expression_activity_LR_target_evidence.tsv'),sep='\t',na='NA');cat('INTEGRATION_COMPLETE\n')
